#!/usr/bin/env python3
"""Collect actual license texts for code redistributed by the Linux binaries/UI.

Run after go mod download and frontend/npm ci, with the pinned build toolchain.
--check compares generated bytes without changing the checkout. No network API,
credentials, or host configuration is accessed by this script itself.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess

root = Path(__file__).resolve().parent.parent
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
env = {**os.environ, "GOOS": "linux", "GOARCH": "amd64", "CGO_ENABLED": "0"}
raw = subprocess.check_output(["go", "list", "-deps", "-json", "./cmd/..."], cwd=root, env=env).decode()
decoder = json.JSONDecoder()
modules = {}
while raw.strip():
    item, end = decoder.raw_decode(raw.lstrip())
    raw = raw.lstrip()[end:]
    module = item.get("Module", {})
    if module and not module.get("Main"):
        if module.get("Replace"):
            raise SystemExit("review replaced module before generating notices: " + module["Path"])
        modules[module["Path"]] = (module["Version"], Path(module["Dir"]), "Go binary")

go_version = subprocess.check_output(["go", "env", "GOVERSION"], cwd=root).decode().strip()
go_root = Path(subprocess.check_output(["go", "env", "GOROOT"], cwd=root).decode().strip())
modules["Go standard library and runtime"] = (go_version, go_root, "Go binary")
lock = json.loads((root / "frontend/package-lock.json").read_text())
for path, metadata in lock["packages"].items():
    if not path or metadata.get("dev") or metadata.get("optional"):
        continue
    directory = root / "frontend" / path
    installed = json.loads((directory / "package.json").read_text())
    if installed["version"] != metadata["version"]:
        raise SystemExit("installed package does not match lock: " + path)
    modules[installed["name"]] = (metadata["version"], directory, "Embedded browser UI")

outputs = {}
components = []
for name, (version, directory, use) in sorted(modules.items()):
    texts = sorted(path for path in directory.iterdir() if path.is_file() and re.match(r"^(?:licen[cs]e|copying|notice|patents)(?:[.-].*)?$", path.name, re.I))
    if not any(re.match(r"^(?:licen[cs]e|copying)", path.name, re.I) for path in texts):
        raise SystemExit("license text unavailable: " + name)
    slug = re.sub(r"[^A-Za-z0-9._-]", "_", name)
    files = []
    for path in texts:
        target = f"licenses/{slug}/{path.name}"
        data = path.read_bytes()
        outputs[target] = data
        files.append({"path": target, "sha256": hashlib.sha256(data).hexdigest()})
    components.append({"name": name, "version": version, "redistributed_in": use, "license_files": files})
outputs["licenses/manifest.json"] = (json.dumps({"schema_version": "xinsight.third-party-notices.v1", "target": "linux/amd64; embedded UI", "components": components}, indent=2) + "\n").encode()
lines = ["# Third-party notices", "", "X-Insight's own code is licensed under Apache-2.0. The components below retain their original licenses. Their unmodified license, notice, and patent texts are included in `licenses/` and in built release payloads.", "", "This inventory is generated from the Linux command dependency graph, the pinned Go runtime, and the production frontend lockfile. Development-only tools are not redistributed in these binaries; their packages retain their own license files. Historical reference documents require their own provenance review and are not covered by this inventory.", "", "| Component | Version | Distribution | License texts |", "| --- | --- | --- | --- |"]
for item in components:
    links = ", ".join(f"[{Path(f['path']).name}]({f['path']})" for f in item["license_files"])
    lines.append(f"| {item['name']} | {item['version']} | {item['redistributed_in']} | {links} |")
lines += ["", "Regenerate with `python3 scripts/collect-third-party-notices.py`; verify with `--check`. See `licenses/manifest.json` for exact text digests.", ""]
outputs["THIRD_PARTY_NOTICES.md"] = "\n".join(lines).encode()
for relative, data in outputs.items():
    path = root / relative
    if args.check:
        if not path.is_file() or path.read_bytes() != data:
            raise SystemExit("third-party notice differs: " + relative)
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
print(f"{'verified' if args.check else 'collected'} {len(components)} redistributed components and {len(outputs)} notice files")
